INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_2_math_u4_L02_basic#1','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'mc','auto','비 3：4에서 후항은 어느 수인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"mc","stem":"비 3：4에서 후항은 어느 수인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M6-2-u4-X03"},{"t":"7","mis":"M6-2-u4-X20"},{"t":"12","mis":"M6-2-u4-X20"}],"explanation":["기호 ：의 앞에 있는 수를 전항, 뒤에 있는 수를 후항이라고 해요.","3：4에서 전항은 3, 후항은 4예요.","그래서 후항은 4예요."],"variant_rule":{"alt":[{"stem":"비 5：8에서 전항은 어느 수인가요?","options":[{"t":"5","correct":true},{"t":"8","mis":"M6-2-u4-X03"},{"t":"13","mis":"M6-2-u4-X20"},{"t":"40","mis":"M6-2-u4-X20"}],"explanation":["기호 ：의 앞에 있는 수를 전항, 뒤에 있는 수를 후항이라고 해요.","5：8에서 전항은 5, 후항은 8이에요.","그래서 전항은 5예요."]},{"stem":"비 7：2에서 후항은 어느 수인가요?","options":[{"t":"2","correct":true},{"t":"7","mis":"M6-2-u4-X03"},{"t":"9","mis":"M6-2-u4-X20"},{"t":"14","mis":"M6-2-u4-X20"}],"explanation":["기호 ：의 앞에 있는 수를 전항, 뒤에 있는 수를 후항이라고 해요.","7：2에서 전항은 7, 후항은 2예요.","그래서 후항은 2예요."]}]}}'::jsonb),
('g6_2_math_u4_L02_basic#2','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'mc','auto','학생 7명 중에서 안경을 쓴 학생은 2명이에요. 전체 학생 수에 대한 안경을 쓴 학생 수의 비율은 얼마인가요?',ARRAY['M6-2-u4-X03']::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":1,"kind":"mc","stem":"학생 7명 중에서 안경을 쓴 학생은 2명이에요. 전체 학생 수에 대한 안경을 쓴 학생 수의 비율은 얼마인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨7/2⟩","mis":"M6-2-u4-X03"},{"t":"⟨2/9⟩","mis":"M6-2-u4-X03"},{"t":"⟨7/9⟩","mis":"M6-2-u4-X03"}],"explanation":["비율은 (비교하는 양) ÷ (기준량)이에요.","2：7에서 비교하는 양은 2, 기준량은 7이에요.","비율은 2 ÷ 7 = ⟨2/7⟩예요."],"variant_rule":{"alt":[{"stem":"학생 8명 중에서 우산을 가져온 학생은 3명이에요. 전체 학생 수에 대한 우산을 가져온 학생 수의 비율은 얼마인가요?","options":[{"t":"⟨3/8⟩","correct":true},{"t":"⟨8/3⟩","mis":"M6-2-u4-X03"},{"t":"⟨3/11⟩","mis":"M6-2-u4-X03"},{"t":"⟨8/11⟩","mis":"M6-2-u4-X03"}],"explanation":["비율은 (비교하는 양) ÷ (기준량)이에요.","3：8에서 비교하는 양은 3, 기준량은 8이에요.","비율은 3 ÷ 8 = ⟨3/8⟩이에요."]},{"stem":"학생 9명 중에서 자전거를 타는 학생은 4명이에요. 전체 학생 수에 대한 자전거를 타는 학생 수의 비율은 얼마인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨9/4⟩","mis":"M6-2-u4-X03"},{"t":"⟨4/13⟩","mis":"M6-2-u4-X03"},{"t":"⟨9/13⟩","mis":"M6-2-u4-X03"}],"explanation":["비율은 (비교하는 양) ÷ (기준량)이에요.","4：9에서 비교하는 양은 4, 기준량은 9예요.","비율은 4 ÷ 9 = ⟨4/9⟩예요."]}]}}'::jsonb),
('g6_2_math_u4_L02_basic#3','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'sa','auto','7：2의 전항과 후항에 똑같이 5를 곱했어요. 35：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"7：2의 전항과 후항에 똑같이 5를 곱했어요. 35：□에서 □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 7에 5를 곱해 35가 되었으니 후항 2에도 5를 곱해요.","2 × 5 = 10 — 35：10이에요."],"variant_rule":{"alt":[{"stem":"3：4의 전항과 후항에 똑같이 6을 곱했어요. 18：□에서 □에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 3에 6을 곱해 18이 되었으니 후항 4에도 6을 곱해요.","4 × 6 = 24 — 18：24예요."]},{"stem":"2：3의 전항과 후항에 똑같이 7을 곱했어요. 14：□에서 □에 알맞은 수는 얼마인가요?","answer":["21"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 2에 7을 곱해 14가 되었으니 후항 3에도 7을 곱해요.","3 × 7 = 21 — 14：21이에요."]}]}}'::jsonb),
('g6_2_math_u4_L02_basic#4','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'sa','auto','45：30의 전항과 후항을 똑같이 15로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"45：30의 전항과 후항을 똑같이 15로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 45를 15로 나누면 3이에요.","후항도 30 ÷ 15 = 2 — 3：2예요."],"variant_rule":{"alt":[{"stem":"12：20의 전항과 후항을 똑같이 4로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?","answer":["5"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 12를 4로 나누면 3이에요.","후항도 20 ÷ 4 = 5 — 3：5예요."]},{"stem":"35：14의 전항과 후항을 똑같이 7로 나누었어요. 5：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 35를 7로 나누면 5예요.","후항도 14 ÷ 7 = 2 — 5：2예요."]}]}}'::jsonb),
('g6_2_math_u4_L02_basic#5','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'sa','auto','비눗방울 용액과 물을 2：1로 섞어요. 용액을 4컵 넣으면 물은 몇 컵을 넣어야 하나요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u4-C1","difficulty":2,"kind":"sa","stem":"비눗방울 용액과 물을 2：1로 섞어요. 용액을 4컵 넣으면 물은 몇 컵을 넣어야 하나요?","answer":["2"],"explanation":["2：1에서 앞의 수 2가 4가 되었으니 2배예요.","비율이 같으려면 뒤의 수도 똑같이 2배 해야 해요.","1 × 2 = 2예요."],"variant_rule":{"alt":[{"stem":"비눗방울 용액과 물을 2：1로 섞어요. 용액을 6컵 넣으면 물은 몇 컵을 넣어야 하나요?","answer":["3"],"explanation":["2：1에서 앞의 수 2가 6이 되었으니 3배예요.","비율이 같으려면 뒤의 수도 똑같이 3배 해야 해요.","1 × 3 = 3이에요."]},{"stem":"비눗방울 용액과 물을 3：1로 섞어요. 용액을 9컵 넣으면 물은 몇 컵을 넣어야 하나요?","answer":["3"],"explanation":["3：1에서 앞의 수 3이 9가 되었으니 3배예요.","비율이 같으려면 뒤의 수도 똑같이 3배 해야 해요.","1 × 3 = 3이에요."]}]}}'::jsonb),
('g6_2_math_u4_L02_basic#6','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'mc','auto','2：3과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":6,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"2：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"4：6","correct":true},{"t":"4：5","mis":"M6-2-u4-X01"},{"t":"6：4","mis":"M6-2-u4-X03"},{"t":"4：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","2：3의 두 항에 똑같이 2를 곱하면 4：6이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."],"variant_rule":{"alt":[{"stem":"4：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"12：9","correct":true},{"t":"7：6","mis":"M6-2-u4-X01"},{"t":"9：12","mis":"M6-2-u4-X03"},{"t":"12：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","4：3의 두 항에 똑같이 3을 곱하면 12：9예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]},{"stem":"5：2와 비율이 같은 비는 어느 것인가요?","options":[{"t":"10：4","correct":true},{"t":"7：4","mis":"M6-2-u4-X01"},{"t":"4：10","mis":"M6-2-u4-X03"},{"t":"10：2","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","5：2의 두 항에 똑같이 2를 곱하면 10：4예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]}]}}'::jsonb),
('g6_2_math_u4_L02_basic#7','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'mc','auto','14：10과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":7,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"14：10과 비율이 같은 비는 어느 것인가요?","options":[{"t":"7：5","correct":true},{"t":"12：8","mis":"M6-2-u4-X01"},{"t":"5：7","mis":"M6-2-u4-X03"},{"t":"7：10","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","14：10의 두 항을 똑같이 2로 나누면 7：5예요.","같은 수를 빼거나 순서를 바꾼 비는 비율이 달라요."],"variant_rule":{"alt":[{"stem":"12：20과 비율이 같은 비는 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"8：16","mis":"M6-2-u4-X01"},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：20","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","12：20의 두 항을 똑같이 4로 나누면 3：5예요.","같은 수를 빼거나 순서를 바꾼 비는 비율이 달라요."]},{"stem":"18：12와 비율이 같은 비는 어느 것인가요?","options":[{"t":"3：2","correct":true},{"t":"12：6","mis":"M6-2-u4-X01"},{"t":"2：3","mis":"M6-2-u4-X03"},{"t":"3：12","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","18：12의 두 항을 똑같이 6으로 나누면 3：2예요.","같은 수를 빼거나 순서를 바꾼 비는 비율이 달라요."]}]}}'::jsonb),
('g6_2_math_u4_L02_basic#8','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'sa','auto','꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 초록 색종이가 14장이면 빨간 색종이는 몇 장이 필요한가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u4-C1","difficulty":2,"kind":"sa","stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 초록 색종이가 14장이면 빨간 색종이는 몇 장이 필요한가요?","answer":["21"],"explanation":["2：3에서 앞의 수 2가 14가 되었으니 7배예요.","비율이 같으려면 뒤의 수도 똑같이 7배 해야 해요.","3 × 7 = 21이에요."],"variant_rule":{"alt":[{"stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 초록 색종이가 10장이면 빨간 색종이는 몇 장이 필요한가요?","answer":["15"],"explanation":["2：3에서 앞의 수 2가 10이 되었으니 5배예요.","비율이 같으려면 뒤의 수도 똑같이 5배 해야 해요.","3 × 5 = 15예요."]},{"stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 초록 색종이가 16장이면 빨간 색종이는 몇 장이 필요한가요?","answer":["24"],"explanation":["2：3에서 앞의 수 2가 16이 되었으니 8배예요.","비율이 같으려면 뒤의 수도 똑같이 8배 해야 해요.","3 × 8 = 24예요."]}]}}'::jsonb),
('g6_2_math_u4_L02_basic#9','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'mc','auto','6：4와 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":9,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"6：4와 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?","options":[{"t":"전항과 후항에 2를 더해 8：6을 구한다","correct":true},{"t":"전항과 후항에 2를 곱해 12：8을 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항을 2로 나누어 3：2를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 3을 곱해 18：12를 구한다","mis":"M6-2-u4-X19"}],"explanation":["비율이 같은 비는 두 항에 0이 아닌 같은 수를 곱하거나 나누어 만들어요.","12：8, 3：2, 18：12는 모두 비율이 ⟨3/2⟩이에요.","8：6은 비율이 ⟨4/3⟩ — 같은 수를 더하는 것은 비의 성질이 아니에요."],"variant_rule":{"alt":[{"stem":"9：6과 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?","options":[{"t":"전항과 후항에서 3을 빼서 6：3을 구한다","correct":true},{"t":"전항과 후항을 3으로 나누어 3：2를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 2를 곱해 18：12를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 4를 곱해 36：24를 구한다","mis":"M6-2-u4-X19"}],"explanation":["비율이 같은 비는 두 항에 같은 수를 곱하거나 나누어 만들어요.","3：2, 18：12, 36：24는 모두 비율이 ⟨3/2⟩이에요.","6：3은 비율이 2 — 같은 수를 빼는 것은 비의 성질이 아니에요."]},{"stem":"10：4와 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?","options":[{"t":"전항과 후항에 5를 더해 15：9를 구한다","correct":true},{"t":"전항과 후항을 2로 나누어 5：2를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 3을 곱해 30：12를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 10을 곱해 100：40을 구한다","mis":"M6-2-u4-X19"}],"explanation":["비율이 같은 비는 두 항에 같은 수를 곱하거나 나누어 만들어요.","5：2, 30：12, 100：40은 모두 비율이 ⟨5/2⟩예요.","15：9는 비율이 ⟨5/3⟩ — 더하기는 비의 성질이 아니에요."]}]}}'::jsonb),
('g6_2_math_u4_L02_basic#10','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',3,'ox','auto','2：3의 전항과 후항에 똑같이 0을 곱해도 비율은 그대로예요.',ARRAY['M6-2-u4-X04']::text[],true,'{"seq":10,"concept":"M6-2-u4-C1","difficulty":3,"kind":"ox","stem":"2：3의 전항과 후항에 똑같이 0을 곱해도 비율은 그대로예요.","answer":"X","reason_options":[{"t":"0을 곱하면 0：0이 되어 비율을 말할 수 없기 때문에","correct":true},{"t":"0도 같은 수이니 곱하거나 나누어도 비율이 그대로이기 때문에","mis":"M6-2-u4-X04"}],"mis":"M6-2-u4-X04","explanation":["비의 성질은 0이 아닌 같은 수를 곱할 때만 써요.","2：3에 0을 곱하면 0：0이 돼요.","0：0은 비율을 나타낼 수 없어요."],"variant_rule":{"alt":[{"stem":"6：9의 전항과 후항을 똑같이 0으로 나누어도 비율은 그대로예요.","answer":"X","reason_options":[{"t":"어떤 수도 0으로는 나눌 수 없기 때문에","correct":true},{"t":"0도 같은 수이니 곱하거나 나누어도 비율이 그대로이기 때문에","mis":"M6-2-u4-X04"}],"explanation":["비의 성질은 0이 아닌 같은 수로 나눌 때만 써요.","0으로 나누는 계산은 할 수 없어요.","그래서 6：9를 0으로 나눌 수 없어요."]},{"stem":"4：5의 전항과 후항에 0이 아닌 같은 수를 곱해야 비율이 그대로예요.","answer":"O","reason_options":[{"t":"0을 곱하면 0：0이 되어 비율을 말할 수 없기 때문에","correct":true},{"t":"0도 같은 수이니 곱하거나 나누어도 비율이 그대로이기 때문에","mis":"M6-2-u4-X04"}],"explanation":["4：5에 3을 곱한 12：15는 비율이 ⟨4/5⟩로 같아요.","0을 곱하면 0：0이 돼요.","그래서 「0이 아닌」 같은 수라는 조건이 붙어요."]}]}}'::jsonb),
('g6_2_math_u4_L02_challenge#1','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',2,'sa','auto','4：9의 전항과 후항에 똑같이 3을 곱했어요. 12：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":2,"kind":"sa","stem":"4：9의 전항과 후항에 똑같이 3을 곱했어요. 12：□에서 □에 알맞은 수는 얼마인가요?","answer":["27"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 4에 3을 곱해 12가 되었으니 후항 9에도 3을 곱해요.","9 × 3 = 27 — 12：27이에요."],"variant_rule":{"alt":[{"stem":"5：6의 전항과 후항에 똑같이 4를 곱했어요. 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 5에 4를 곱해 20이 되었으니 후항 6에도 4를 곱해요.","6 × 4 = 24 — 20：24예요."]},{"stem":"8：3의 전항과 후항에 똑같이 5를 곱했어요. 40：□에서 □에 알맞은 수는 얼마인가요?","answer":["15"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 8에 5를 곱해 40이 되었으니 후항 3에도 5를 곱해요.","3 × 5 = 15 — 40：15예요."]}]}}'::jsonb),
('g6_2_math_u4_L02_challenge#2','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',2,'mc','auto','24：36의 전항과 후항을 똑같이 12로 나누면 어떤 비가 되나요?',ARRAY['M6-2-u4-X02','M6-2-u4-X01','M6-2-u4-X03']::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"24：36의 전항과 후항을 똑같이 12로 나누면 어떤 비가 되나요?","options":[{"t":"2：3","correct":true},{"t":"2：36","mis":"M6-2-u4-X02"},{"t":"12：24","mis":"M6-2-u4-X01"},{"t":"3：2","mis":"M6-2-u4-X03"}],"explanation":["전항과 후항을 똑같이 12로 나누어요.","24 ÷ 12 = 2, 36 ÷ 12 = 3이에요.","그래서 2：3 — 비율은 그대로예요."],"variant_rule":{"alt":[{"stem":"28：21의 전항과 후항을 똑같이 7로 나누면 어떤 비가 되나요?","options":[{"t":"4：3","correct":true},{"t":"4：21","mis":"M6-2-u4-X02"},{"t":"21：14","mis":"M6-2-u4-X01"},{"t":"3：4","mis":"M6-2-u4-X03"}],"explanation":["전항과 후항을 똑같이 7로 나누어요.","28 ÷ 7 = 4, 21 ÷ 7 = 3이에요.","그래서 4：3 — 비율은 그대로예요."]},{"stem":"40：64의 전항과 후항을 똑같이 8로 나누면 어떤 비가 되나요?","options":[{"t":"5：8","correct":true},{"t":"5：64","mis":"M6-2-u4-X02"},{"t":"32：56","mis":"M6-2-u4-X01"},{"t":"8：5","mis":"M6-2-u4-X03"}],"explanation":["전항과 후항을 똑같이 8로 나누어요.","40 ÷ 8 = 5, 64 ÷ 8 = 8이에요.","그래서 5：8 — 비율은 그대로예요."]}]}}'::jsonb),
