('g6_2_math_u4_L05_challenge#1','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',2,'sa','auto','□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."],"variant_rule":{"alt":[{"stem":"□：5 = 8：10에서 □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × 8 = 40이므로 10 × □ = 40이에요.","□ = 40 ÷ 10 = 4예요."]},{"stem":"□：7 = 12：21에서 □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 7 × 12 = 84이므로 21 × □ = 84예요.","□ = 84 ÷ 21 = 4예요."]}]}}'::jsonb),
('g6_2_math_u4_L05_challenge#2','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',2,'sa','auto','0.4：□ = 2：15에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"0.4：□ = 2：15에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 0.4 × 15 = 6이므로 2 × □ = 6이에요.","□ = 6 ÷ 2 = 3이에요."],"variant_rule":{"alt":[{"stem":"1.5：□ = 3：8에서 □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 1.5 × 8 = 12이므로 3 × □ = 12예요.","□ = 12 ÷ 3 = 4예요."]},{"stem":"0.6：□ = 3：10에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 0.6 × 10 = 6이므로 3 × □ = 6이에요.","□ = 6 ÷ 3 = 2예요."]}]}}'::jsonb),
('g6_2_math_u4_L05_challenge#3','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'sa','auto','⟨1/2⟩：⟨1/3⟩ = □：4에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C6","difficulty":3,"kind":"sa","stem":"⟨1/2⟩：⟨1/3⟩ = □：4에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 ⟨1/2⟩ × 4 = 2이므로 ⟨1/3⟩ × □ = 2예요.","□ = 2 ÷ ⟨1/3⟩ = 6이에요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩：⟨1/5⟩ = □：8에서 □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 ⟨1/4⟩ × 8 = 2이므로 ⟨1/5⟩ × □ = 2예요.","□ = 2 ÷ ⟨1/5⟩ = 10이에요."]},{"stem":"⟨2/3⟩：⟨1/2⟩ = □：6에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 ⟨2/3⟩ × 6 = 4이므로 ⟨1/2⟩ × □ = 4예요.","□ = 4 ÷ ⟨1/2⟩ = 8이에요."]}]}}'::jsonb),
('g6_2_math_u4_L05_challenge#4','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'mc','auto','외항의 곱과 내항의 곱을 견주었을 때 비례식이 아닌 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":4,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"외항의 곱과 내항의 곱을 견주었을 때 비례식이 아닌 것은 어느 것인가요?","options":[{"t":"6：9 = 3：5","correct":true},{"t":"6：9 = 2：3","mis":"M6-2-u4-X19"},{"t":"4：10 = 6：15","mis":"M6-2-u4-X19"},{"t":"12：8 = 3：2","mis":"M6-2-u4-X19"}],"explanation":["6：9 = 2：3은 18과 18, 4：10 = 6：15는 60과 60이에요.","12：8 = 3：2는 24와 24예요.","6：9 = 3：5는 외항의 곱 30, 내항의 곱 27로 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 외항의 곱과 내항의 곱을 견주었을 때 비례식이 아닌 것은 어느 것인가요?","options":[{"t":"5：4 = 15：13","correct":true},{"t":"5：4 = 15：12","mis":"M6-2-u4-X19"},{"t":"2：7 = 6：21","mis":"M6-2-u4-X19"},{"t":"9：3 = 6：2","mis":"M6-2-u4-X19"}],"explanation":["5：4 = 15：12는 60과 60, 2：7 = 6：21은 42와 42예요.","9：3 = 6：2는 18과 18이에요.","5：4 = 15：13은 외항의 곱 65, 내항의 곱 60으로 달라요."]},{"stem":"이번에는 다른 보기예요. 외항의 곱과 내항의 곱을 견주었을 때 비례식이 아닌 것은 어느 것인가요?","options":[{"t":"3：8 = 6：15","correct":true},{"t":"3：8 = 6：16","mis":"M6-2-u4-X19"},{"t":"10：4 = 5：2","mis":"M6-2-u4-X19"},{"t":"7：3 = 14：6","mis":"M6-2-u4-X19"}],"explanation":["3：8 = 6：16은 48과 48, 10：4 = 5：2는 20과 20이에요.","7：3 = 14：6은 42와 42예요.","3：8 = 6：15는 외항의 곱 45, 내항의 곱 48로 달라요."]}]}}'::jsonb),
('g6_2_math_u4_L05_challenge#5','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'mc','auto','비례식 3：5 = □：△에서 내항의 곱이 60이에요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u4-X12','M6-2-u4-X11','M6-2-u4-X20']::text[],true,'{"seq":5,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"비례식 3：5 = □：△에서 내항의 곱이 60이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"12","correct":true},{"t":"60","mis":"M6-2-u4-X12"},{"t":"20","mis":"M6-2-u4-X11"},{"t":"36","mis":"M6-2-u4-X20"}],"explanation":["내항은 안쪽의 5와 □예요.","5 × □ = 60이에요.","□ = 60 ÷ 5 = 12예요."],"variant_rule":{"alt":[{"stem":"비례식 2：7 = □：△에서 내항의 곱이 56이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"56","mis":"M6-2-u4-X12"},{"t":"28","mis":"M6-2-u4-X11"},{"t":"16","mis":"M6-2-u4-X20"}],"explanation":["내항은 안쪽의 7과 □예요.","7 × □ = 56이에요.","□ = 56 ÷ 7 = 8이에요."]},{"stem":"비례식 4：9 = □：△에서 내항의 곱이 72예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"72","mis":"M6-2-u4-X12"},{"t":"18","mis":"M6-2-u4-X11"},{"t":"32","mis":"M6-2-u4-X20"}],"explanation":["내항은 안쪽의 9와 □예요.","9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."]}]}}'::jsonb),
('g6_2_math_u4_L05_challenge#6','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'ox','auto','비례식 8：6 = 12：9에서 외항의 곱과 내항의 곱은 모두 72예요.',ARRAY['M6-2-u4-X11']::text[],true,'{"seq":6,"concept":"M6-2-u4-C6","difficulty":3,"kind":"ox","stem":"비례식 8：6 = 12：9에서 외항의 곱과 내항의 곱은 모두 72예요.","answer":"O","reason_options":[{"t":"8 × 9와 6 × 12가 모두 72이기 때문에","correct":true},{"t":"8 × 12와 6 × 9가 같기 때문에","mis":"M6-2-u4-X11"}],"mis":"M6-2-u4-X11","explanation":["외항은 8과 9, 내항은 6과 12예요.","8 × 9 = 72, 6 × 12 = 72예요.","두 곱이 모두 72로 같아요."],"variant_rule":{"alt":[{"stem":"비례식 4：10 = 6：15에서 외항의 곱과 내항의 곱은 모두 60이에요.","answer":"O","reason_options":[{"t":"4 × 15와 10 × 6이 모두 60이기 때문에","correct":true},{"t":"4 × 6과 10 × 15가 같기 때문에","mis":"M6-2-u4-X11"}],"explanation":["외항은 4와 15, 내항은 10과 6이에요.","4 × 15 = 60, 10 × 6 = 60이에요.","두 곱이 모두 60으로 같아요."]},{"stem":"비례식 3：7 = 9：21에서 외항의 곱과 내항의 곱은 모두 27이에요.","answer":"X","reason_options":[{"t":"외항의 곱 3 × 21과 내항의 곱 7 × 9는 모두 63이기 때문에","correct":true},{"t":"3 × 9가 27이라 외항의 곱이 27이기 때문에","mis":"M6-2-u4-X11"}],"explanation":["외항은 3과 21, 내항은 7과 9예요.","3 × 21 = 63, 7 × 9 = 63이에요.","27은 전항끼리 곱한 값이에요."]}]}}'::jsonb),
('g6_2_math_u4_L05_challenge#7','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'match','auto','비례식의 □에 알맞은 수를 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C6","difficulty":3,"kind":"match","stem":"비례식의 □에 알맞은 수를 이으세요.","pairs":[{"l":"□：4 = 6：8","r":"3"},{"l":"5：□ = 10：14","r":"7"},{"l":"9：12 = 3：□","r":"4"}],"mis":"M6-2-u4-X12","explanation":["□ × 8 = 4 × 6 = 24 → □ = 3이에요.","5 × 14 = □ × 10 = 70 → □ = 7이에요.","9 × □ = 12 × 3 = 36 → □ = 4예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비례식의 □에 알맞은 수를 이으세요.","pairs":[{"l":"□：6 = 4：8","r":"3"},{"l":"2：□ = 6：15","r":"5"},{"l":"8：10 = 12：□","r":"15"}],"explanation":["□ × 8 = 6 × 4 = 24 → □ = 3이에요.","2 × 15 = □ × 6 = 30 → □ = 5예요.","8 × □ = 10 × 12 = 120 → □ = 15예요."]}]}}'::jsonb),
('g6_2_math_u4_L05_challenge#8','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',4,'mc','auto','어떤 비례식에서 외항의 곱이 72이고 내항 하나가 9예요. 다른 내항은 얼마인가요?',ARRAY['M6-2-u4-X20','M6-2-u4-X12']::text[],true,'{"seq":8,"concept":"M6-2-u4-C6","difficulty":4,"kind":"mc","stem":"어떤 비례식에서 외항의 곱이 72이고 내항 하나가 9예요. 다른 내항은 얼마인가요?","options":[{"t":"8","correct":true},{"t":"63","mis":"M6-2-u4-X20"},{"t":"81","mis":"M6-2-u4-X20"},{"t":"648","mis":"M6-2-u4-X12"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","그래서 내항의 곱도 72예요.","9 × □ = 72 — □ = 8이에요."],"variant_rule":{"alt":[{"stem":"어떤 비례식에서 외항의 곱이 84이고 내항 하나가 12예요. 다른 내항은 얼마인가요?","options":[{"t":"7","correct":true},{"t":"72","mis":"M6-2-u4-X20"},{"t":"96","mis":"M6-2-u4-X20"},{"t":"1008","mis":"M6-2-u4-X12"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","그래서 내항의 곱도 84예요.","12 × □ = 84 — □ = 7이에요."]},{"stem":"어떤 비례식에서 내항의 곱이 90이고 외항 하나가 6이에요. 다른 외항은 얼마인가요?","options":[{"t":"15","correct":true},{"t":"84","mis":"M6-2-u4-X20"},{"t":"96","mis":"M6-2-u4-X20"},{"t":"540","mis":"M6-2-u4-X12"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","그래서 외항의 곱도 90이에요.","6 × □ = 90 — □ = 15예요."]}]}}'::jsonb),
('g6_2_math_u4_L05_challenge#9','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',4,'essay','teacher','민지의 막대는 5 cm, 그림자는 7 cm이고, 다운이의 막대는 10 cm, 그림자는 14 cm예요. 비례식 5：7 = 10：14에서 외항의 곱과 내항의 곱을 구해 견주고, 두 곱이 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C6","difficulty":4,"kind":"essay","stem":"민지의 막대는 5 cm, 그림자는 7 cm이고, 다운이의 막대는 10 cm, 그림자는 14 cm예요. 비례식 5：7 = 10：14에서 외항의 곱과 내항의 곱을 구해 견주고, 두 곱이 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 외항의 곱은 5 × 14 = 70, 내항의 곱은 7 × 10 = 70으로 같다. 비례식은 두 비의 비율이 같다는 뜻이고, 10：14는 5：7의 두 항에 똑같이 2를 곱한 것이어서 외항의 곱과 내항의 곱이 모두 5 × 7 × 2가 되기 때문이다.","scoring_points":["외항의 곱 70을 구했는가","내항의 곱 70을 구해 같음을 보였는가","비율이 같다(같은 수를 곱했다)는 까닭을 썼는가"]},"explanation":["5 × 14 = 70이에요.","7 × 10 = 70이에요.","비율이 같아서 생기는 결과예요."]}'::jsonb),
('g6_2_math_u4_L05_challenge#10','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',4,'essay','teacher','사과 9개로 사과주스 4병을 만들어요. 친구가 9：4 = □：12를 「9 × 4 = □ × 12」로 풀어 □ = 3이라고 했어요. 잘못된 점을 쓰고 바르게 풀어 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C6","difficulty":4,"kind":"essay","stem":"사과 9개로 사과주스 4병을 만들어요. 친구가 9：4 = □：12를 「9 × 4 = □ × 12」로 풀어 □ = 3이라고 했어요. 잘못된 점을 쓰고 바르게 풀어 보세요.","answer_guide":{"answer":"예: 비례식에서는 외항끼리, 내항끼리 곱해야 하는데 친구는 한 비의 두 수를 곱했다. 외항의 곱 9 × 12 = 108과 내항의 곱 4 × □가 같으므로 □ = 27이다. 사과는 27개 필요하다.","scoring_points":["잘못된 점(외항끼리·내항끼리 곱하지 않음)을 썼는가","9 × 12 = 4 × □를 세웠는가","□ = 27을 구했는가"]},"explanation":["외항끼리, 내항끼리 곱해요.","9 × 12 = 108 = 4 × □예요.","□ = 27 — 사과 27개예요."]}'::jsonb),
('g6_2_math_u4_L06_basic#1','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'sa','auto','직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 하면 2：8000 = □：40000이에요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 하면 2：8000 = □：40000이에요. □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["구하려는 값을 □라 하고 비례식 2：8000 = □：40000을 세워요.","외항의 곱 2 × 40000 = 80000이므로 8000 × □ = 80000이에요.","□ = 80000 ÷ 8000 = 10 — 10이에요."],"variant_rule":{"alt":[{"stem":"직거래 장터에서 쌀 3 kg을 9000원에 팔아요. 27000원으로 살 수 있는 쌀의 무게를 □ kg이라 하면 3：9000 = □：27000이에요. □에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["구하려는 값을 □라 하고 비례식 3：9000 = □：27000을 세워요.","외항의 곱 3 × 27000 = 81000이므로 9000 × □ = 81000이에요.","□ = 81000 ÷ 9000 = 9 — 9예요."]},{"stem":"직거래 장터에서 쌀 4 kg을 12000원에 팔아요. 36000원으로 살 수 있는 쌀의 무게를 □ kg이라 하면 4：12000 = □：36000이에요. □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["구하려는 값을 □라 하고 비례식 4：12000 = □：36000을 세워요.","외항의 곱 4 × 36000 = 144000이므로 12000 × □ = 144000이에요.","□ = 144000 ÷ 12000 = 12 — 12예요."]}]}}'::jsonb),
('g6_2_math_u4_L06_basic#2','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'mc','auto','어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X20']::text[],true,'{"seq":2,"concept":"M6-2-u4-C7","difficulty":1,"kind":"mc","stem":"어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"140 km","correct":true},{"t":"55 km","mis":"M6-2-u4-X14"},{"t":"840 km","mis":"M6-2-u4-X12"},{"t":"280 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 6：40 = 21：□를 세워요.","내항의 곱 40 × 21 = 840이므로 6 × □ = 840이에요.","□ = 840 ÷ 6 = 140 — 140 km예요."],"variant_rule":{"alt":[{"stem":"어느 전기차는 5 kWh의 전기 에너지로 30 km를 이동해요. 20 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"120 km","correct":true},{"t":"45 km","mis":"M6-2-u4-X14"},{"t":"600 km","mis":"M6-2-u4-X12"},{"t":"240 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 5：30 = 20：□를 세워요.","내항의 곱 30 × 20 = 600이므로 5 × □ = 600이에요.","□ = 600 ÷ 5 = 120 — 120 km예요."]},{"stem":"어느 전기차는 4 kWh의 전기 에너지로 25 km를 이동해요. 12 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"75 km","correct":true},{"t":"33 km","mis":"M6-2-u4-X14"},{"t":"300 km","mis":"M6-2-u4-X12"},{"t":"150 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 4：25 = 12：□를 세워요.","내항의 곱 25 × 12 = 300이므로 4 × □ = 300이에요.","□ = 300 ÷ 4 = 75 — 75 km예요."]}]}}'::jsonb),
('g6_2_math_u4_L06_basic#3','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'sa','auto','계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["60"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 180：□를 세워요.","내항의 곱 1 × 180 = 180이므로 3 × □ = 180이에요.","□ = 180 ÷ 3 = 60 — 60 g예요."],"variant_rule":{"alt":[{"stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 240 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["80"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 240：□를 세워요.","내항의 곱 1 × 240 = 240이므로 3 × □ = 240이에요.","□ = 240 ÷ 3 = 80 — 80 g예요."]},{"stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 150 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["50"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 150：□를 세워요.","내항의 곱 1 × 150 = 150이므로 3 × □ = 150이에요.","□ = 150 ÷ 3 = 50 — 50 g예요."]}]}}'::jsonb),
('g6_2_math_u4_L06_basic#4','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'mc','auto','사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 사진 속 형의 키와 첨성대 높이의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":4,"concept":"M6-2-u4-C7","difficulty":1,"kind":"mc","stem":"사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 사진 속 형의 키와 첨성대 높이의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：6","correct":true},{"t":"25：150","mis":"M6-2-u4-X05"},{"t":"6：1","mis":"M6-2-u4-X03"},{"t":"2.5：150","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 25：150이에요.","25와 150의 최대공약수 25로 나누면 1：6이에요.","그래서 가장 간단한 자연수의 비는 1：6이에요."],"variant_rule":{"alt":[{"stem":"사진 속 형의 키는 1.5 cm, 첨성대의 높이는 12 cm예요. 사진 속 형의 키와 첨성대 높이의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：8","correct":true},{"t":"15：120","mis":"M6-2-u4-X05"},{"t":"8：1","mis":"M6-2-u4-X03"},{"t":"1.5：120","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 15：120이에요.","15와 120의 최대공약수 15로 나누면 1：8이에요.","그래서 가장 간단한 자연수의 비는 1：8이에요."]},{"stem":"사진 속 형의 키는 3.5 cm, 첨성대의 높이는 14 cm예요. 사진 속 형의 키와 첨성대 높이의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：4","correct":true},{"t":"35：140","mis":"M6-2-u4-X05"},{"t":"4：1","mis":"M6-2-u4-X03"},{"t":"3.5：140","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 35：140이에요.","35와 140의 최대공약수 35로 나누면 1：4예요.","그래서 가장 간단한 자연수의 비는 1：4예요."]}]}}'::jsonb),
('g6_2_math_u4_L06_basic#5','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'sa','auto','사진 속 형의 키와 첨성대 높이의 비가 1：6이고 형의 실제 키는 1.5 m예요. 1：6 = 1.5：□에서 첨성대의 실제 높이는 몇 m인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u4-C7","difficulty":2,"kind":"sa","stem":"사진 속 형의 키와 첨성대 높이의 비가 1：6이고 형의 실제 키는 1.5 m예요. 1：6 = 1.5：□에서 첨성대의 실제 높이는 몇 m인가요?","answer":["9"],"explanation":["구하려는 값을 □라 하고 비례식 1：6 = 1.5：□를 세워요.","내항의 곱 6 × 1.5 = 9이므로 1 × □ = 9예요.","□ = 9 ÷ 1 = 9 — 9예요."],"variant_rule":{"alt":[{"stem":"사진 속 형의 키와 첨성대 높이의 비가 1：4이고 형의 실제 키는 1.5 m예요. 1：4 = 1.5：□에서 첨성대의 실제 높이는 몇 m인가요?","answer":["6"],"explanation":["구하려는 값을 □라 하고 비례식 1：4 = 1.5：□를 세워요.","내항의 곱 4 × 1.5 = 6이므로 1 × □ = 6이에요.","□ = 6 ÷ 1 = 6 — 6이에요."]},{"stem":"사진 속 형의 키와 첨성대 높이의 비가 1：8이고 형의 실제 키는 1.5 m예요. 1：8 = 1.5：□에서 첨성대의 실제 높이는 몇 m인가요?","answer":["12"],"explanation":["구하려는 값을 □라 하고 비례식 1：8 = 1.5：□를 세워요.","내항의 곱 8 × 1.5 = 12이므로 1 × □ = 12예요.","□ = 12 ÷ 1 = 12 — 12예요."]}]}}'::jsonb),
('g6_2_math_u4_L06_basic#6','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'mc','auto','페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?',ARRAY['M6-2-u4-X13','M6-2-u4-X14','M6-2-u4-X12']::text[],true,'{"seq":6,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"5 L","correct":true},{"t":"720 L","mis":"M6-2-u4-X13"},{"t":"16 L","mis":"M6-2-u4-X14"},{"t":"240 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 4：48 = □：60을 세워요.","외항의 곱 4 × 60 = 240이므로 48 × □ = 240이에요.","□ = 240 ÷ 48 = 5 — 5 L예요."],"variant_rule":{"alt":[{"stem":"페인트 3 L로 담장 27 m²를 칠할 수 있어요. 담장 45 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"5 L","correct":true},{"t":"405 L","mis":"M6-2-u4-X13"},{"t":"21 L","mis":"M6-2-u4-X14"},{"t":"135 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 3：27 = □：45를 세워요.","외항의 곱 3 × 45 = 135이므로 27 × □ = 135예요.","□ = 135 ÷ 27 = 5 — 5 L예요."]},{"stem":"페인트 6 L로 담장 54 m²를 칠할 수 있어요. 담장 72 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"8 L","correct":true},{"t":"648 L","mis":"M6-2-u4-X13"},{"t":"24 L","mis":"M6-2-u4-X14"},{"t":"432 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 6：54 = □：72를 세워요.","외항의 곱 6 × 72 = 432이므로 54 × □ = 432예요.","□ = 432 ÷ 54 = 8 — 8 L예요."]}]}}'::jsonb),
('g6_2_math_u4_L06_basic#7','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'sa','auto','물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸려요. 들이가 50 L인 수조를 가득 채우려면 몇 초가 걸리나요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C7","difficulty":2,"kind":"sa","stem":"물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸려요. 들이가 50 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["80"],"explanation":["구하려는 값을 □라 하고 비례식 15：24 = 50：□를 세워요.","내항의 곱 24 × 50 = 1200이므로 15 × □ = 1200이에요.","□ = 1200 ÷ 15 = 80 — 80초예요."],"variant_rule":{"alt":[{"stem":"물이 일정하게 나오는 수도로 들이가 10 L인 수조를 가득 채우는 데 18초가 걸려요. 들이가 25 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["45"],"explanation":["구하려는 값을 □라 하고 비례식 10：18 = 25：□를 세워요.","내항의 곱 18 × 25 = 450이므로 10 × □ = 450이에요.","□ = 450 ÷ 10 = 45 — 45초예요."]},{"stem":"물이 일정하게 나오는 수도로 들이가 12 L인 수조를 가득 채우는 데 20초가 걸려요. 들이가 30 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["50"],"explanation":["구하려는 값을 □라 하고 비례식 12：20 = 30：□를 세워요.","내항의 곱 20 × 30 = 600이므로 12 × □ = 600이에요.","□ = 600 ÷ 12 = 50 — 50초예요."]}]}}'::jsonb),
('g6_2_math_u4_L06_basic#8','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'mc','auto','2：8000 = □：40000에서 □를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":8,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"2：8000 = □：40000에서 □를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"2：8000의 전항과 후항에 5를 더한다","correct":true},{"t":"외항의 곱과 내항의 곱이 같음을 이용한다","mis":"M6-2-u4-X19"},{"t":"2：8000의 전항과 후항에 5를 곱한다","mis":"M6-2-u4-X19"},{"t":"2：8000의 비율과 □：40000의 비율이 같음을 이용한다","mis":"M6-2-u4-X19"}],"explanation":["2：8000의 후항 8000에 5를 곱하면 40000이에요.","그래서 전항에도 5를 곱해 □ = 10이에요.","같은 수를 더하는 것은 비의 성질이 아니에요."],"variant_rule":{"alt":[{"stem":"3：9000 = □：27000에서 □를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"3：9000의 전항과 후항에 3을 더한다","correct":true},{"t":"외항의 곱과 내항의 곱이 같음을 이용한다","mis":"M6-2-u4-X19"},{"t":"3：9000의 전항과 후항에 3을 곱한다","mis":"M6-2-u4-X19"},{"t":"3：9000의 비율과 □：27000의 비율이 같음을 이용한다","mis":"M6-2-u4-X19"}],"explanation":["3：9000의 후항 9000에 3을 곱하면 27000이에요.","그래서 전항에도 3을 곱해 □ = 9예요.","같은 수를 더하는 것은 비의 성질이 아니에요."]},{"stem":"6：40 = □：160에서 □를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"6：40의 전항과 후항에 4를 더한다","correct":true},{"t":"외항의 곱과 내항의 곱이 같음을 이용한다","mis":"M6-2-u4-X19"},{"t":"6：40의 전항과 후항에 4를 곱한다","mis":"M6-2-u4-X19"},{"t":"6：40의 비율과 □：160의 비율이 같음을 이용한다","mis":"M6-2-u4-X19"}],"explanation":["6：40의 후항 40에 4를 곱하면 160이에요.","그래서 전항에도 4를 곱해 □ = 24예요.","같은 수를 더하는 것은 비의 성질이 아니에요."]}]}}'::jsonb),
('g6_2_math_u4_L06_basic#9','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'sa','auto','사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u4-C7","difficulty":2,"kind":"sa","stem":"사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?","answer":["27"],"explanation":["구하려는 값을 □라 하고 비례식 9：4 = □：12를 세워요.","외항의 곱 9 × 12 = 108이므로 4 × □ = 108이에요.","□ = 108 ÷ 4 = 27 — 27개예요."],"variant_rule":{"alt":[{"stem":"사과 6개로 사과주스 4병을 만들 수 있어요. 사과주스 10병을 만들려면 사과가 몇 개 필요한가요?","answer":["15"],"explanation":["구하려는 값을 □라 하고 비례식 6：4 = □：10을 세워요.","외항의 곱 6 × 10 = 60이므로 4 × □ = 60이에요.","□ = 60 ÷ 4 = 15 — 15개예요."]},{"stem":"사과 8개로 사과주스 3병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?","answer":["32"],"explanation":["구하려는 값을 □라 하고 비례식 8：3 = □：12를 세워요.","외항의 곱 8 × 12 = 96이므로 3 × □ = 96이에요.","□ = 96 ÷ 3 = 32 — 32개예요."]}]}}'::jsonb),
('g6_2_math_u4_L06_basic#10','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',3,'mc','auto','쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?',ARRAY['M6-2-u4-X13']::text[],true,'{"seq":10,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"2：8000 = □：40000","correct":true},{"t":"2：8000 = 40000：□","mis":"M6-2-u4-X13"},{"t":"8000：2 = □：40000","mis":"M6-2-u4-X13"},{"t":"2：40000 = □：8000","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 2：8000 = □：40000이에요."],"variant_rule":{"alt":[{"stem":"전기차가 6 kWh로 40 km를 가요. 21 kWh로 갈 수 있는 거리를 □ km라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"6：40 = 21：□","correct":true},{"t":"6：40 = □：21","mis":"M6-2-u4-X13"},{"t":"40：6 = 21：□","mis":"M6-2-u4-X13"},{"t":"6：□ = 40：21","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 6：40 = 21：□예요."]},{"stem":"사과 9개로 주스 4병을 만들어요. 주스 12병에 드는 사과를 □개라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"9：4 = □：12","correct":true},{"t":"9：4 = 12：□","mis":"M6-2-u4-X13"},{"t":"4：9 = □：12","mis":"M6-2-u4-X13"},{"t":"9：12 = □：4","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 9：4 = □：12예요."]}]}}'::jsonb),
('g6_2_math_u4_L06_challenge#1','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',2,'mc','auto','어느 전기차는 7 kWh의 전기 에너지로 50 km를 이동해요. 28 kWh로는 몇 km를 갈 수 있나요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X20']::text[],true,'{"seq":1,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"어느 전기차는 7 kWh의 전기 에너지로 50 km를 이동해요. 28 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"200 km","correct":true},{"t":"71 km","mis":"M6-2-u4-X14"},{"t":"1400 km","mis":"M6-2-u4-X12"},{"t":"400 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 7：50 = 28：□를 세워요.","내항의 곱 50 × 28 = 1400이므로 7 × □ = 1400이에요.","□ = 1400 ÷ 7 = 200 — 200 km예요."],"variant_rule":{"alt":[{"stem":"어느 전기차는 3 kWh의 전기 에너지로 20 km를 이동해요. 15 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"100 km","correct":true},{"t":"32 km","mis":"M6-2-u4-X14"},{"t":"300 km","mis":"M6-2-u4-X12"},{"t":"200 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 3：20 = 15：□를 세워요.","내항의 곱 20 × 15 = 300이므로 3 × □ = 300이에요.","□ = 300 ÷ 3 = 100 — 100 km예요."]},{"stem":"어느 전기차는 8 kWh의 전기 에너지로 60 km를 이동해요. 20 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"150 km","correct":true},{"t":"72 km","mis":"M6-2-u4-X14"},{"t":"1200 km","mis":"M6-2-u4-X12"},{"t":"300 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 8：60 = 20：□를 세워요.","내항의 곱 60 × 20 = 1200이므로 8 × □ = 1200이에요.","□ = 1200 ÷ 8 = 150 — 150 km예요."]}]}}'::jsonb),
('g6_2_math_u4_L06_challenge#2','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',2,'sa','auto','빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C7","difficulty":2,"kind":"sa","stem":"빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["8"],"explanation":["구하려는 값을 □라 하고 비례식 3：2 = 12：□를 세워요.","내항의 곱 2 × 12 = 24이므로 3 × □ = 24예요.","□ = 24 ÷ 3 = 8 — 8컵예요."],"variant_rule":{"alt":[{"stem":"빵 반죽에 밀가루와 우유를 5：3으로 넣어요. 밀가루를 15컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["9"],"explanation":["구하려는 값을 □라 하고 비례식 5：3 = 15：□를 세워요.","내항의 곱 3 × 15 = 45이므로 5 × □ = 45예요.","□ = 45 ÷ 5 = 9 — 9컵예요."]},{"stem":"빵 반죽에 밀가루와 우유를 4：3으로 넣어요. 밀가루를 20컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["15"],"explanation":["구하려는 값을 □라 하고 비례식 4：3 = 20：□를 세워요.","내항의 곱 3 × 20 = 60이므로 4 × □ = 60이에요.","□ = 60 ÷ 4 = 15 — 15컵예요."]}]}}'::jsonb),
('g6_2_math_u4_L06_challenge#3','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','비눗방울 용액과 물을 2：1로 섞었어요. 용액을 2컵 더 넣어 4컵으로 늘리면서 친구는 물도 2컵 더 넣어 3컵이라고 했어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u4-X02','M6-2-u4-X14','M6-2-u4-X13']::text[],true,'{"seq":3,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"비눗방울 용액과 물을 2：1로 섞었어요. 용액을 2컵 더 넣어 4컵으로 늘리면서 친구는 물도 2컵 더 넣어 3컵이라고 했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"같은 수를 더하면 비율이 달라져서 — 물은 2컵이어야 해요","correct":true},{"t":"용액을 더 넣으면 물은 그대로 두어야 해서","mis":"M6-2-u4-X02"},{"t":"물을 4컵 더 넣어야 해서","mis":"M6-2-u4-X14"},{"t":"용액과 물의 순서를 바꾸어야 해서","mis":"M6-2-u4-X13"}],"explanation":["2：1에서 용액이 2컵 → 4컵이면 2배예요.","물도 2배 — 1 × 2 = 2컵이에요.","같은 수만큼 더하는 것은 같은 비율로 늘린 것이 아니에요."],"variant_rule":{"alt":[{"stem":"비눗방울 용액과 물을 3：1로 섞었어요. 용액을 3컵 더 넣어 6컵으로 늘리면서 친구는 물도 3컵 더 넣어 4컵이라고 했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"같은 수를 더하면 비율이 달라져서 — 물은 2컵이어야 해요","correct":true},{"t":"용액을 더 넣으면 물은 그대로 두어야 해서","mis":"M6-2-u4-X02"},{"t":"물을 6컵 더 넣어야 해서","mis":"M6-2-u4-X14"},{"t":"용액과 물의 순서를 바꾸어야 해서","mis":"M6-2-u4-X13"}],"explanation":["3：1에서 용액이 3컵 → 6컵이면 2배예요.","물도 2배 — 1 × 2 = 2컵이에요.","같은 수만큼 더하는 것은 같은 비율로 늘린 것이 아니에요."]},{"stem":"비눗방울 용액과 물을 2：3으로 섞었어요. 용액을 2컵 더 넣어 4컵으로 늘리면서 친구는 물도 2컵 더 넣어 5컵이라고 했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"같은 수를 더하면 비율이 달라져서 — 물은 6컵이어야 해요","correct":true},{"t":"용액을 더 넣으면 물은 그대로 두어야 해서","mis":"M6-2-u4-X02"},{"t":"물을 4컵 더 넣어야 해서","mis":"M6-2-u4-X14"},{"t":"용액과 물의 순서를 바꾸어야 해서","mis":"M6-2-u4-X13"}],"explanation":["2：3에서 용액이 2컵 → 4컵이면 2배예요.","물도 2배 — 3 × 2 = 6컵이에요.","같은 수만큼 더하는 것은 같은 비율로 늘린 것이 아니에요."]}]}}'::jsonb),
('g6_2_math_u4_L06_challenge#4','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','공책 4권이 3600원이에요. 공책 9권은 얼마인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X20']::text[],true,'{"seq":4,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"공책 4권이 3600원이에요. 공책 9권은 얼마인가요?","options":[{"t":"8100원","correct":true},{"t":"3605원","mis":"M6-2-u4-X14"},{"t":"32400원","mis":"M6-2-u4-X12"},{"t":"16200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 4：3600 = 9：□를 세워요.","내항의 곱 3600 × 9 = 32400이므로 4 × □ = 32400이에요.","□ = 32400 ÷ 4 = 8100 — 8100원예요."],"variant_rule":{"alt":[{"stem":"공책 3권이 2400원이에요. 공책 7권은 얼마인가요?","options":[{"t":"5600원","correct":true},{"t":"2404원","mis":"M6-2-u4-X14"},{"t":"16800원","mis":"M6-2-u4-X12"},{"t":"11200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 3：2400 = 7：□를 세워요.","내항의 곱 2400 × 7 = 16800이므로 3 × □ = 16800이에요.","□ = 16800 ÷ 3 = 5600 — 5600원예요."]},{"stem":"공책 5권이 6000원이에요. 공책 8권은 얼마인가요?","options":[{"t":"9600원","correct":true},{"t":"6003원","mis":"M6-2-u4-X14"},{"t":"48000원","mis":"M6-2-u4-X12"},{"t":"19200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 5：6000 = 8：□를 세워요.","내항의 곱 6000 × 8 = 48000이므로 5 × □ = 48000이에요.","□ = 48000 ÷ 5 = 9600 — 9600원예요."]}]}}'::jsonb),
('g6_2_math_u4_L06_challenge#5','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X20']::text[],true,'{"seq":5,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"15 km","correct":true},{"t":"8.5 km","mis":"M6-2-u4-X14"},{"t":"30 km","mis":"M6-2-u4-X20"},{"t":"22.5 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 1：2 = 7.5：□를 세워요.","내항의 곱 2 × 7.5 = 15이므로 1 × □ = 15예요.","□ = 15 ÷ 1 = 15 — 15 km예요."],"variant_rule":{"alt":[{"stem":"지도에서 2 cm는 실제 거리 5 km예요. 지도에서 7 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"17.5 km","correct":true},{"t":"2.8 km","mis":"M6-2-u4-X13"},{"t":"10 km","mis":"M6-2-u4-X14"},{"t":"35 km","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 2：5 = 7：□를 세워요.","내항의 곱 5 × 7 = 35이므로 2 × □ = 35예요.","□ = 35 ÷ 2 = 17.5 — 17.5 km예요."]},{"stem":"지도에서 1 cm는 실제 거리 3 km예요. 지도에서 4.5 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"13.5 km","correct":true},{"t":"1.5 km","mis":"M6-2-u4-X13"},{"t":"6.5 km","mis":"M6-2-u4-X14"},{"t":"27 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 1：3 = 4.5：□를 세워요.","내항의 곱 3 × 4.5 = 13.5이므로 1 × □ = 13.5예요.","□ = 13.5 ÷ 1 = 13.5 — 13.5 km예요."]}]}}'::jsonb),
('g6_2_math_u4_L06_challenge#6','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','6：40 = 21：□를 비의 성질로 풀려고 해요. 알맞은 방법은 어느 것인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X02','M6-2-u4-X12']::text[],true,'{"seq":6,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"6：40 = 21：□를 비의 성질로 풀려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"6에 3.5를 곱하면 21이니 40에도 3.5를 곱한다","correct":true},{"t":"6에 15를 더하면 21이니 40에도 15를 더한다","mis":"M6-2-u4-X14"},{"t":"6에 3.5를 곱하면 21이니 40은 그대로 둔다","mis":"M6-2-u4-X02"},{"t":"40에 21을 곱하고 6으로 나눈다","mis":"M6-2-u4-X12"}],"explanation":["비의 성질로 풀 때는 두 항에 같은 수를 곱해요.","6 × 3.5 = 21이에요.","그래서 □ = 40 × 3.5 = 140이에요."],"variant_rule":{"alt":[{"stem":"2：8000 = 10：□를 비의 성질로 풀려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"2에 5를 곱하면 10이니 8000에도 5를 곱한다","correct":true},{"t":"2에 8을 더하면 10이니 8000에도 8을 더한다","mis":"M6-2-u4-X14"},{"t":"2에 5를 곱하면 10이니 8000은 그대로 둔다","mis":"M6-2-u4-X02"},{"t":"8000에 10을 곱하고 2로 나눈다","mis":"M6-2-u4-X12"}],"explanation":["비의 성질로 풀 때는 두 항에 같은 수를 곱해요.","2 × 5 = 10이에요.","그래서 □ = 8000 × 5 = 40000이에요."]},{"stem":"3：1 = 180：□를 비의 성질로 풀려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"3에 60을 곱하면 180이니 1에도 60을 곱한다","correct":true},{"t":"3에 177을 더하면 180이니 1에도 177을 더한다","mis":"M6-2-u4-X14"},{"t":"3에 60을 곱하면 180이니 1은 그대로 둔다","mis":"M6-2-u4-X02"},{"t":"1에 180을 곱하고 3으로 나눈다","mis":"M6-2-u4-X12"}],"explanation":["비의 성질로 풀 때는 두 항에 같은 수를 곱해요.","3 × 60 = 180이에요.","그래서 □ = 1 × 60 = 60이에요."]}]}}'::jsonb),
('g6_2_math_u4_L06_challenge#7','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'match','auto','문제와 알맞은 답을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C7","difficulty":3,"kind":"match","stem":"문제와 알맞은 답을 이으세요.","pairs":[{"l":"쌀 2 kg에 8000원 — 10 kg은?","r":"40000원"},{"l":"6 kWh로 40 km — 21 kWh로는?","r":"140 km"},{"l":"사과 9개로 주스 4병 — 12병에는?","r":"사과 27개"}],"mis":"M6-2-u4-X13","explanation":["2：8000 = 10：□ → □ = 40000이에요.","6：40 = 21：□ → □ = 140이에요.","9：4 = □：12 → □ = 27이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 문제와 알맞은 답을 이으세요.","pairs":[{"l":"페인트 4 L로 48 m² — 60 m²에는?","r":"5 L"},{"l":"15 L에 24초 — 50 L는?","r":"80초"},{"l":"계피와 에탄올 3：1 — 계피 180 g이면?","r":"에탄올 60 g"}],"explanation":["4：48 = □：60 → □ = 5예요.","15：24 = 50：□ → □ = 80이에요.","3：1 = 180：□ → □ = 60이에요."]}]}}'::jsonb),
('g6_2_math_u4_L06_challenge#8','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',4,'mc','auto','두 양이 같은 비율로 늘지 않아 비례식을 세워 풀 수 없는 것은 어느 것인가요?',ARRAY['M6-2-u4-X14']::text[],true,'{"seq":8,"concept":"M6-2-u4-C7","difficulty":4,"kind":"mc","stem":"두 양이 같은 비율로 늘지 않아 비례식을 세워 풀 수 없는 것은 어느 것인가요?","options":[{"t":"형은 12살, 동생은 9살일 때 형이 15살이 되면 동생은 몇 살인지 구하기","correct":true},{"t":"쌀 2 kg이 8000원일 때 6 kg의 값 구하기","mis":"M6-2-u4-X14"},{"t":"사과 9개로 주스 4병일 때 8병에 드는 사과 구하기","mis":"M6-2-u4-X14"},{"t":"6 kWh로 40 km를 갈 때 12 kWh로 가는 거리 구하기","mis":"M6-2-u4-X14"}],"explanation":["비례식은 한 양이 몇 배가 되면 다른 양도 똑같이 몇 배가 될 때 세워요.","나이는 해마다 똑같이 1살씩 늘어 몇 배가 되지 않아요.","그래서 나이 문제는 비례식이 아니라 덧셈으로 풀어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 두 양이 같은 비율로 늘지 않아 비례식을 세워 풀 수 없는 것은 어느 것인가요?","options":[{"t":"언니는 14살, 나는 10살일 때 언니가 21살이 되면 나는 몇 살인지 구하기","correct":true},{"t":"공책 4권이 3600원일 때 8권의 값 구하기","mis":"M6-2-u4-X14"},{"t":"15 L에 24초가 걸릴 때 30 L에 걸리는 시간 구하기","mis":"M6-2-u4-X14"},{"t":"페인트 4 L로 48 m²를 칠할 때 8 L로 칠하는 넓이 구하기","mis":"M6-2-u4-X14"}],"explanation":["비례식은 한 양이 몇 배가 되면 다른 양도 똑같이 몇 배가 될 때 세워요.","나이는 해마다 똑같이 1살씩 늘어 몇 배가 되지 않아요.","그래서 나이 문제는 비례식이 아니라 덧셈으로 풀어요."]}]}}'::jsonb),
('g6_2_math_u4_L06_challenge#9','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',4,'essay','teacher','직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 쌀을 몇 kg 살 수 있는지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 쌀을 몇 kg 살 수 있는지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.","answer_guide":{"answer":"예: 살 수 있는 쌀을 □ kg이라 하면 2：8000 = □：40000이다. ① 외항의 곱 2 × 40000 = 80000과 내항의 곱 8000 × □가 같으므로 □ = 10이다. ② 8000에 5를 곱하면 40000이므로 2에도 5를 곱해 □ = 10이다. 쌀 10 kg을 살 수 있다.","scoring_points":["2：8000 = □：40000을 세웠는가","비례식의 성질로 10을 구했는가","비의 성질로 10을 구했는가"]},"explanation":["2：8000 = □：40000이에요.","2 × 40000 = 8000 × □ → □ = 10이에요.","8000 × 5 = 40000 → □ = 2 × 5 = 10이에요."]}'::jsonb),
('g6_2_math_u4_L06_challenge#10','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',4,'essay','teacher','페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하는 데 필요한 페인트의 양을 비례식을 세워 구하고, 이 문제에서 비례식을 세울 수 있는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하는 데 필요한 페인트의 양을 비례식을 세워 구하고, 이 문제에서 비례식을 세울 수 있는 까닭을 써 보세요.","answer_guide":{"answer":"예: 필요한 페인트를 □ L라 하면 4：48 = □：60이다. 4 × 60 = 48 × □ = 240이므로 □ = 5, 페인트는 5 L가 필요하다. 칠하는 넓이가 늘면 페인트의 양도 같은 비율로 늘기 때문에 비례식을 세울 수 있다.","scoring_points":["4：48 = □：60을 세웠는가","□ = 5(L)를 구했는가","두 양이 같은 비율로 변한다는 까닭을 썼는가"]},"explanation":["4：48 = □：60이에요.","4 × 60 = 240 = 48 × □ → □ = 5예요.","넓이와 페인트 양이 같은 비율로 늘어요."]}'::jsonb),
('g6_2_math_u4_L07_basic#1','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'sa','auto','삼촌이 보내 주신 꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C8","difficulty":1,"kind":"sa","stem":"삼촌이 보내 주신 꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?","answer":["6"],"explanation":["비 2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽의 몫은 전체의 ⟨2/3⟩예요.","9 × ⟨2/3⟩ = 6(개)예요."],"variant_rule":{"alt":[{"stem":"꿀떡 12개를 리엘이와 동생이 3：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?","answer":["9"],"explanation":["비 3：1은 한 묶음이 3 + 1 = 4칸이에요.","앞쪽의 몫은 전체의 ⟨3/4⟩이에요.","12 × ⟨3/4⟩ = 9(개)예요."]},{"stem":"꿀떡 15개를 리엘이와 동생이 2：3으로 나누어 먹어요. 동생은 몇 개를 먹나요?","answer":["9"],"explanation":["비 2：3은 한 묶음이 2 + 3 = 5칸이에요.","뒤쪽의 몫은 전체의 ⟨3/5⟩이에요.","15 × ⟨3/5⟩ = 9(개)예요."]}]}}'::jsonb),
('g6_2_math_u4_L07_basic#2','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'mc','auto','정후네 가족 3명과 연아네 가족 4명이 사과 28개를 땄어요. 가족 수의 비 3：4로 나누면 정후네 가족은 몇 개를 가지나요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":2,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"정후네 가족 3명과 연아네 가족 4명이 사과 28개를 땄어요. 가족 수의 비 3：4로 나누면 정후네 가족은 몇 개를 가지나요?","options":[{"t":"12개","correct":true},{"t":"16개","mis":"M6-2-u4-X17"},{"t":"4개","mis":"M6-2-u4-X16"},{"t":"21개","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨3/7⟩이에요.","28 × ⟨3/7⟩ = 12(개)예요."],"variant_rule":{"alt":[{"stem":"정후네 가족 3명과 연아네 가족 4명이 사과 35개를 땄어요. 가족 수의 비 3：4로 나누면 연아네 가족은 몇 개를 가지나요?","options":[{"t":"20개","correct":true},{"t":"15개","mis":"M6-2-u4-X17"},{"t":"5개","mis":"M6-2-u4-X16"},{"t":"25개","mis":"M6-2-u4-X20"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","35 × ⟨4/7⟩ = 20(개)예요."]},{"stem":"정후네 가족 5명과 연아네 가족 3명이 사과 24개를 땄어요. 가족 수의 비 5：3으로 나누면 정후네 가족은 몇 개를 가지나요?","options":[{"t":"15개","correct":true},{"t":"9개","mis":"M6-2-u4-X17"},{"t":"3개","mis":"M6-2-u4-X16"},{"t":"40개","mis":"M6-2-u4-X16"}],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","24 × ⟨5/8⟩ = 15(개)예요."]}]}}'::jsonb),
('g6_2_math_u4_L07_basic#3','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'mc','auto','용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":3,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"2000원","mis":"M6-2-u4-X16"},{"t":"15000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨3/5⟩이에요.","10000 × ⟨3/5⟩ = 6000(원)예요."],"variant_rule":{"alt":[{"stem":"용돈 8000원을 학용품과 장난감을 사는 데 5：3으로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?","options":[{"t":"5000원","correct":true},{"t":"1600원","mis":"M6-2-u4-X15"},{"t":"3000원","mis":"M6-2-u4-X17"},{"t":"1000원","mis":"M6-2-u4-X16"}],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","8000 × ⟨5/8⟩ = 5000(원)예요."]},{"stem":"용돈 12000원을 학용품과 장난감을 사는 데 1：2로 나누어 써요. 장난감에 쓸 용돈은 얼마인가요?","options":[{"t":"8000원","correct":true},{"t":"6000원","mis":"M6-2-u4-X15"},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"24000원","mis":"M6-2-u4-X16"}],"explanation":["비 1：2는 한 묶음이 1 + 2 = 3칸이에요.","뒤쪽의 몫은 전체의 ⟨2/3⟩예요.","12000 × ⟨2/3⟩ = 8000(원)예요."]}]}}'::jsonb),
('g6_2_math_u4_L07_basic#4','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'mc','auto','수지와 형진이가 2800원짜리 장난감 값을 3：4로 나누어 내요. 수지는 얼마를 내야 하나요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":4,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"수지와 형진이가 2800원짜리 장난감 값을 3：4로 나누어 내요. 수지는 얼마를 내야 하나요?","options":[{"t":"1200원","correct":true},{"t":"1600원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"},{"t":"2100원","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨3/7⟩이에요.","2800 × ⟨3/7⟩ = 1200(원)예요."],"variant_rule":{"alt":[{"stem":"수지와 형진이가 3600원짜리 장난감 값을 4：5로 나누어 내요. 수지는 얼마를 내야 하나요?","options":[{"t":"1600원","correct":true},{"t":"900원","mis":"M6-2-u4-X15"},{"t":"2000원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"}],"explanation":["비 4：5는 한 묶음이 4 + 5 = 9칸이에요.","앞쪽의 몫은 전체의 ⟨4/9⟩예요.","3600 × ⟨4/9⟩ = 1600(원)예요."]},{"stem":"수지와 형진이가 2000원짜리 장난감 값을 2：3으로 나누어 내요. 형진이는 얼마를 내야 하나요?","options":[{"t":"1200원","correct":true},{"t":"800원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"},{"t":"3000원","mis":"M6-2-u4-X16"}],"explanation":["비 2：3은 한 묶음이 2 + 3 = 5칸이에요.","뒤쪽의 몫은 전체의 ⟨3/5⟩이에요.","2000 × ⟨3/5⟩ = 1200(원)예요."]}]}}'::jsonb),
('g6_2_math_u4_L07_basic#5','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'sa','auto','햇빛 모둠은 5명, 달빛 모둠은 3명이에요. 색종이 72장을 모둠원 수에 따라 나누면 햇빛 모둠은 몇 장을 받나요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u4-C8","difficulty":2,"kind":"sa","stem":"햇빛 모둠은 5명, 달빛 모둠은 3명이에요. 색종이 72장을 모둠원 수에 따라 나누면 햇빛 모둠은 몇 장을 받나요?","answer":["45"],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","72 × ⟨5/8⟩ = 45(장)예요."],"variant_rule":{"alt":[{"stem":"햇빛 모둠은 5명, 달빛 모둠은 3명이에요. 색종이 64장을 모둠원 수에 따라 나누면 달빛 모둠은 몇 장을 받나요?","answer":["24"],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","뒤쪽의 몫은 전체의 ⟨3/8⟩이에요.","64 × ⟨3/8⟩ = 24(장)예요."]},{"stem":"햇빛 모둠은 4명, 달빛 모둠은 3명이에요. 색종이 56장을 모둠원 수에 따라 나누면 햇빛 모둠은 몇 장을 받나요?","answer":["32"],"explanation":["비 4：3은 한 묶음이 4 + 3 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨4/7⟩예요.","56 × ⟨4/7⟩ = 32(장)예요."]}]}}'::jsonb),
('g6_2_math_u4_L07_basic#6','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'mc','auto','1시간 동안 달리기와 줄넘기를 했어요. 달리기와 줄넘기를 한 시간의 비가 7：5일 때 달리기를 한 시간은 몇 분인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":6,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"1시간 동안 달리기와 줄넘기를 했어요. 달리기와 줄넘기를 한 시간의 비가 7：5일 때 달리기를 한 시간은 몇 분인가요?","options":[{"t":"35분","correct":true},{"t":"25분","mis":"M6-2-u4-X17"},{"t":"5분","mis":"M6-2-u4-X16"},{"t":"84분","mis":"M6-2-u4-X16"}],"explanation":["비 7：5는 한 묶음이 7 + 5 = 12칸이에요.","앞쪽의 몫은 전체의 ⟨7/12⟩이에요.","60 × ⟨7/12⟩ = 35(분)예요."],"variant_rule":{"alt":[{"stem":"1시간 동안 달리기와 줄넘기를 했어요. 달리기와 줄넘기를 한 시간의 비가 2：3일 때 달리기를 한 시간은 몇 분인가요?","options":[{"t":"24분","correct":true},{"t":"30분","mis":"M6-2-u4-X15"},{"t":"36분","mis":"M6-2-u4-X17"},{"t":"12분","mis":"M6-2-u4-X16"}],"explanation":["비 2：3은 한 묶음이 2 + 3 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨2/5⟩예요.","60 × ⟨2/5⟩ = 24(분)예요."]},{"stem":"1시간 동안 달리기와 줄넘기를 했어요. 달리기와 줄넘기를 한 시간의 비가 3：7일 때 줄넘기를 한 시간은 몇 분인가요?","options":[{"t":"42분","correct":true},{"t":"18분","mis":"M6-2-u4-X17"},{"t":"6분","mis":"M6-2-u4-X16"},{"t":"140분","mis":"M6-2-u4-X16"}],"explanation":["비 3：7은 한 묶음이 3 + 7 = 10칸이에요.","뒤쪽의 몫은 전체의 ⟨7/10⟩이에요.","60 × ⟨7/10⟩ = 42(분)예요."]}]}}'::jsonb),
