('g6_2_math_u4_review_d#14','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C6',1,'sa','auto','비례식 4：5 = 8：10에서 내항의 곱은 얼마인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"비례식 4：5 = 8：10에서 내항의 곱은 얼마인가요?","answer":["40"],"explanation":["내항은 5와 8이에요.","내항의 곱은 5 × 8 = 40이에요.","외항의 곱도 40으로 같아요."],"variant_rule":{"alt":[{"stem":"비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?","answer":["70"],"explanation":["외항은 5와 14예요.","외항의 곱은 5 × 14 = 70이에요.","내항의 곱도 70으로 같아요."]},{"stem":"비례식 9：12 = 3：4에서 외항의 곱은 얼마인가요?","answer":["36"],"explanation":["외항은 9와 4예요.","외항의 곱은 9 × 4 = 36이에요.","내항의 곱도 36으로 같아요."]}]}}'::jsonb),
('g6_2_math_u4_review_d#15','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C6',2,'sa','auto','□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."],"variant_rule":{"alt":[{"stem":"4：5 = 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["25"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × 20 = 100이므로 4 × □ = 100이에요.","□ = 100 ÷ 4 = 25예요."]},{"stem":"10：8 = 15：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 8 × 15 = 120이므로 10 × □ = 120이에요.","□ = 120 ÷ 10 = 12예요."]}]}}'::jsonb),
('g6_2_math_u4_review_d#16','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C6',3,'mc','auto','9：4 = 18：□를 푸는데 친구가 「9 × 18 = 4 × □」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M6-2-u4-X20','M6-2-u4-X09','M6-2-u4-X12']::text[],true,'{"seq":16,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"9：4 = 18：□를 푸는데 친구가 「9 × 18 = 4 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 9 × 18로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","9 × □ = 4 × 18이에요.","□ = 8이에요."],"variant_rule":{"alt":[{"stem":"8：6 = 12：□를 푸는데 친구가 「8 × 12 = 6 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 8 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","8 × □ = 6 × 12예요.","□ = 9예요."]},{"stem":"4：5 = 12：□를 푸는데 친구가 「4 × 12 = 5 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 4 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","4 × □ = 5 × 12예요.","□ = 15예요."]}]}}'::jsonb),
('g6_2_math_u4_review_d#17','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',1,'sa','auto','빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?','{}'::text[],true,'{"seq":17,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["8"],"explanation":["구하려는 값을 □라 하고 비례식 3：2 = 12：□를 세워요.","내항의 곱 2 × 12 = 24이므로 3 × □ = 24예요.","□ = 24 ÷ 3 = 8 — 8컵예요."],"variant_rule":{"alt":[{"stem":"사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?","answer":["27"],"explanation":["구하려는 값을 □라 하고 비례식 9：4 = □：12를 세워요.","외항의 곱 9 × 12 = 108이므로 4 × □ = 108이에요.","□ = 108 ÷ 4 = 27 — 27개예요."]},{"stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["60"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 180：□를 세워요.","내항의 곱 1 × 180 = 180이므로 3 × □ = 180이에요.","□ = 180 ÷ 3 = 60 — 60 g예요."]}]}}'::jsonb),
('g6_2_math_u4_review_d#18','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',2,'mc','auto','지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X20']::text[],true,'{"seq":18,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"15 km","correct":true},{"t":"8.5 km","mis":"M6-2-u4-X14"},{"t":"30 km","mis":"M6-2-u4-X20"},{"t":"22.5 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 1：2 = 7.5：□를 세워요.","내항의 곱 2 × 7.5 = 15이므로 1 × □ = 15예요.","□ = 15 ÷ 1 = 15 — 15 km예요."],"variant_rule":{"alt":[{"stem":"어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"140 km","correct":true},{"t":"55 km","mis":"M6-2-u4-X14"},{"t":"840 km","mis":"M6-2-u4-X12"},{"t":"280 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 6：40 = 21：□를 세워요.","내항의 곱 40 × 21 = 840이므로 6 × □ = 840이에요.","□ = 840 ÷ 6 = 140 — 140 km예요."]},{"stem":"페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"5 L","correct":true},{"t":"720 L","mis":"M6-2-u4-X13"},{"t":"16 L","mis":"M6-2-u4-X14"},{"t":"240 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 4：48 = □：60을 세워요.","외항의 곱 4 × 60 = 240이므로 48 × □ = 240이에요.","□ = 240 ÷ 48 = 5 — 5 L예요."]}]}}'::jsonb),
('g6_2_math_u4_review_d#19','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',3,'mc','auto','페인트 4 L로 담장 48 m²를 칠해요. 담장 60 m²에 드는 페인트를 □ L라 할 때 비례식을 바르게 세운 것은 어느 것인가요?',ARRAY['M6-2-u4-X13']::text[],true,'{"seq":19,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"페인트 4 L로 담장 48 m²를 칠해요. 담장 60 m²에 드는 페인트를 □ L라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"4：48 = □：60","correct":true},{"t":"4：48 = 60：□","mis":"M6-2-u4-X13"},{"t":"48：4 = □：60","mis":"M6-2-u4-X13"},{"t":"4：60 = □：48","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 4：48 = □：60이에요."],"variant_rule":{"alt":[{"stem":"쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"2：8000 = □：40000","correct":true},{"t":"2：8000 = 40000：□","mis":"M6-2-u4-X13"},{"t":"8000：2 = □：40000","mis":"M6-2-u4-X13"},{"t":"2：40000 = □：8000","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 2：8000 = □：40000이에요."]},{"stem":"전기차가 6 kWh로 40 km를 가요. 21 kWh로 갈 수 있는 거리를 □ km라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"6：40 = 21：□","correct":true},{"t":"6：40 = □：21","mis":"M6-2-u4-X13"},{"t":"40：6 = 21：□","mis":"M6-2-u4-X13"},{"t":"6：□ = 40：21","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 6：40 = 21：□예요."]}]}}'::jsonb),
('g6_2_math_u4_review_d#20','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C8',1,'sa','auto','연필 45자루를 형과 동생이 4：5로 나누어요. 동생은 몇 자루를 받나요?','{}'::text[],true,'{"seq":20,"concept":"M6-2-u4-C8","difficulty":1,"kind":"sa","stem":"연필 45자루를 형과 동생이 4：5로 나누어요. 동생은 몇 자루를 받나요?","answer":["25"],"explanation":["비 4：5는 한 묶음이 4 + 5 = 9칸이에요.","뒤쪽의 몫은 전체의 ⟨5/9⟩예요.","45 × ⟨5/9⟩ = 25(자루)예요."],"variant_rule":{"alt":[{"stem":"꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?","answer":["6"],"explanation":["비 2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽의 몫은 전체의 ⟨2/3⟩예요.","9 × ⟨2/3⟩ = 6(개)예요."]},{"stem":"색종이 72장을 햇빛 모둠과 달빛 모둠이 5：3으로 나누어요. 햇빛 모둠은 몇 장을 받나요?","answer":["45"],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","72 × ⟨5/8⟩ = 45(장)예요."]}]}}'::jsonb),
('g6_2_math_u4_review_d#21','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C8',2,'mc','auto','2800원짜리 장난감 값을 수지와 형진이가 3：4로 나누어 내요. 수지는 얼마를 내나요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":21,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"2800원짜리 장난감 값을 수지와 형진이가 3：4로 나누어 내요. 수지는 얼마를 내나요?","options":[{"t":"1200원","correct":true},{"t":"1600원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"},{"t":"2100원","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨3/7⟩이에요.","2800 × ⟨3/7⟩ = 1200(원)예요."],"variant_rule":{"alt":[{"stem":"찰흙 420 g을 3：4로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?","options":[{"t":"240 g","correct":true},{"t":"105 g","mis":"M6-2-u4-X15"},{"t":"180 g","mis":"M6-2-u4-X17"},{"t":"60 g","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","420 × ⟨4/7⟩ = 240( g)예요."]},{"stem":"용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"2000원","mis":"M6-2-u4-X16"},{"t":"15000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨3/5⟩이에요.","10000 × ⟨3/5⟩ = 6000(원)예요."]}]}}'::jsonb),
('g6_2_math_u4_review_d#22','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C8',3,'mc','auto','1800을 2：7로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":22,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"1800을 2：7로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1800 ÷ 2를 하여 900씩 나눈다","correct":true},{"t":"전체를 9칸으로 갈라 2칸과 7칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1800 × ⟨2/9⟩와 1800 × ⟨7/9⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"400과 1400으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：7은 한 묶음이 9칸이라는 뜻이에요.","그래서 1800 × ⟨2/9⟩ = 400, 1800 × ⟨7/9⟩ = 1400이에요.","1800 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."],"variant_rule":{"alt":[{"stem":"1200을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1200 ÷ 2를 하여 600씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1200 × ⟨2/5⟩와 1200 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"480과 720으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1200 × ⟨2/5⟩ = 480, 1200 × ⟨3/5⟩ = 720이에요.","1200 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]},{"stem":"1500을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1500 ÷ 2를 하여 750씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1500 × ⟨2/5⟩와 1500 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"600과 900으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1500 × ⟨2/5⟩ = 600, 1500 × ⟨3/5⟩ = 900이에요.","1500 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]}]}}'::jsonb),
('g6_2_math_u4_review_d#23','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C9',4,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 동하는 몇 원을 받나요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17','M6-2-u4-X20']::text[],true,'{"seq":23,"concept":"M6-2-u4-C9","difficulty":4,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"50000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"100000원","mis":"M6-2-u4-X20"}],"explanation":["먼저 두 친구의 몫은 800000 × ⟨1/4⟩ = 200000(원)예요.","9000원：3000원을 간단히 하면 3：1이에요.","200000 × ⟨1/4⟩ = 50000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"300000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨3/5⟩ = 90000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"90000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨2/5⟩ = 60000(원)예요."]}]}}'::jsonb),
('g6_2_math_u4_review_d#24','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C9',4,'essay','teacher','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 400000원을 회사와 사용자가 3：2로 나누어요. 두 친구의 몫을 낸 사용료(태리 9000원, 동하 6000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 1장, 동하 1장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 400000원을 회사와 사용자가 3：2로 나누어요. 두 친구의 몫을 낸 사용료(태리 9000원, 동하 6000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 1장, 동하 1장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.","answer_guide":{"answer":"예: 두 친구의 몫은 400000 × ⟨2/5⟩ = 160000원이다. 사용료의 비 3：2로 나누면 태리 96000원, 동하 64000원이다. 그림 수의 비 1：1로 나누면 태리 80000원이므로 사용료의 비로 나눌 때 태리가 더 많이 받는다.","scoring_points":["두 친구의 몫 160000원을 먼저 구했는가","사용료의 비로 두 몫을 바르게 구했는가","그림 수의 비로 나눈 태리의 몫과 견주었는가"]},"explanation":["먼저 두 친구의 몫 160000원을 구해요.","사용료의 비로 나누어요.","그림 수의 비로 나눈 몫과 견주어요."]}'::jsonb),
('g6_2_math_u4_review_d#25','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',4,'essay','teacher','설탕 4숟가락로 레몬차 5잔을 만들 수 있어요. 레몬차 15잔을 만들려면 설탕이 몇 숟가락 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"설탕 4숟가락로 레몬차 5잔을 만들 수 있어요. 레몬차 15잔을 만들려면 설탕이 몇 숟가락 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.","answer_guide":{"answer":"예: 필요한 양을 □라 하면 4：5 = □：15이다. ① 외항의 곱과 내항의 곱이 같으므로 4 × 15 = 5 × □, □ = 12이다. ② 후항에 3을 곱했으므로 전항에도 3을 곱해 □ = 12이다.","scoring_points":["4：5 = □：15를 세웠는가","비례식의 성질로 12를 구했는가","비의 성질로 같은 답을 구했는가"]},"explanation":["4：5 = □：15예요.","4 × 15 = 5 × □ → □ = 12예요.","3배 해도 □ = 12예요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('M6-2-u5-C1','math',6,2,'u5',2,'원주 — 원의 중심·반지름·지름을 되짚고 원의 둘레를 원주라 하며, 원 안 정육각형(지름의 3배)과 원 밖 정사각형(지름의 4배)으로 원주가 지름의 3배보다 길고 4배보다 짧음을 알기',ARRAY['6수03-11']::text[],1),
('M6-2-u5-C2','math',6,2,'u5',3,'원주율 — 원의 지름에 대한 원주의 비율이 모든 원에서 일정함을 알고 (원주율) = (원주) ÷ (지름), 끝없이 이어지는 소수라 3.14로 어림해 쓰기',ARRAY['6수03-11']::text[],2),
('M6-2-u5-C3','math',6,2,'u5',4,'원주 구하기 — (원주) = (지름) × (원주율), 반지름만 알면 2를 먼저 곱해 지름을 만든 뒤 원주율을 곱하고, 굴러간 거리 문제에 쓰기',ARRAY['6수03-11']::text[],3),
('M6-2-u5-C4','math',6,2,'u5',4,'지름·반지름 구하기 — (지름) = (원주) ÷ (원주율)로 곱셈을 되짚어 지름과 반지름을 구하고, 원주·지름·반지름이 섞인 원의 크기를 견주기',ARRAY['6수03-11']::text[],4),
('M6-2-u5-C5','math',6,2,'u5',5,'원의 넓이 어림하기 — 모눈 칸(온전한 칸·걸친 칸)과 원 안·밖 정사각형으로 넓이가 들어갈 범위를 찾고, (반지름) × (반지름)의 2배와 4배 사이(약 3배)임을 알기',ARRAY['6수03-12']::text[],5),
('M6-2-u5-C6','math',6,2,'u5',6,'원의 넓이 구하기 — 원을 한없이 잘라 이어 붙인 직사각형(가로 원주의 반, 세로 반지름)으로 (원의 넓이) = (반지름) × (반지름) × (원주율)을 이끌어 내고 쓰기',ARRAY['6수03-12']::text[],6),
('M6-2-u5-C7','math',6,2,'u5',7,'원의 넓이 활용 — 고리 모양은 큰 원에서 작은 원을 빼고, 잘라 옮겨도 넓이는 그대로이며, 반원·사분원·조각은 원의 넓이를 나누어 구하기',ARRAY['6수03-12']::text[],7),
('M6-2-u5-C8','math',6,2,'u5',8,'반지름과 넓이의 관계 — 반지름이 □배가 되면 원주는 □배, 원의 넓이는 반지름을 두 번 곱하므로 □ × □배가 됨을 알고 쓰기',ARRAY['6수03-12']::text[],8)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('M6-2-u5-X01','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C3','M6-2-u5-C4','M6-2-u5-C6']::text[],'원의 중심·반지름·지름을 혼동하거나 (지름) = (반지름) × 2 관계를 거꾸로 쓴다','지름은 반지름 두 개'),
('M6-2-u5-X02','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C2']::text[],'원주를 지름·반지름 같은 선분과 혼동하거나, 원주가 지름의 3배(4배)와 정확히 같다고 단정하거나, 다각형처럼 변을 더해 구하려 한다','3배보다 길고 4배보다 짧아요'),
('M6-2-u5-X03','math',6,'u5',ARRAY['M6-2-u5-C1']::text[],'원 안 정육각형의 한 변을 지름으로, 원 밖 정사각형의 한 변을 반지름으로 바꾸어 본다','육각형 한 변 = 반지름'),
('M6-2-u5-X04','math',6,'u5',ARRAY['M6-2-u5-C2']::text[],'원주율을 (지름) ÷ (원주)나 (원주) ÷ (반지름)으로 구한다(기준량을 잘못 잡음)','기준량은 지름'),
('M6-2-u5-X05','math',6,'u5',ARRAY['M6-2-u5-C2']::text[],'원이 커지면 원주율도 커진다고, 또는 원마다 원주율이 다르다고 본다','원주율은 늘 같아요'),
('M6-2-u5-X06','math',6,'u5',ARRAY['M6-2-u5-C2']::text[],'3.14가 원주율의 정확한 값이라 보거나, 잰 값의 작은 차이를 원주율이 달라서라고 본다','3.14는 어림한 값'),
('M6-2-u5-X07','math',6,'u5',ARRAY['M6-2-u5-C3','M6-2-u5-C4']::text[],'반지름만 주어졌을 때 2를 곱하지 않고 반지름에 바로 원주율을 곱한다','반지름 × 2부터'),
('M6-2-u5-X08','math',6,'u5',ARRAY['M6-2-u5-C3','M6-2-u5-C4']::text[],'원주를 구할 때 나누거나 지름을 구할 때 곱하는 등 곱셈·나눗셈을 거꾸로 쓴다','지름 × 3.14 = 원주'),
('M6-2-u5-X10','math',6,'u5',ARRAY['M6-2-u5-C5']::text[],'넓이 어림에서 온전한 칸과 걸친 칸을 바꾸거나, 범위를 벗어난 값을 고르거나, 어림을 정확한 값으로 단정한다','어림은 범위'),
('M6-2-u5-X11','math',6,'u5',ARRAY['M6-2-u5-C5']::text[],'원 안·밖 정사각형의 넓이가 (반지름) × (반지름)의 몇 배인지(2배·4배) 혼동한다','안은 2개, 밖은 4개'),
('M6-2-u5-X12','math',6,'u5',ARRAY['M6-2-u5-C6','M6-2-u5-C7','M6-2-u5-C8']::text[],'원의 넓이를 원주 식((지름) × (원주율))으로 구하거나 원주와 넓이 식을 바꾸어 쓴다','넓이는 반지름을 두 번'),
('M6-2-u5-X13','math',6,'u5',ARRAY['M6-2-u5-C6','M6-2-u5-C7']::text[],'원의 넓이를 구할 때 반지름 대신 지름을 두 번 곱한다','지름 말고 반지름'),
('M6-2-u5-X14','math',6,'u5',ARRAY['M6-2-u5-C6','M6-2-u5-C8']::text[],'원의 넓이를 구할 때 반지름을 한 번만 곱한다((반지름) × (원주율))','반지름을 두 번'),
('M6-2-u5-X15','math',6,'u5',ARRAY['M6-2-u5-C6']::text[],'원을 잘라 이어 붙인 직사각형의 가로를 원주 전체로, 세로를 지름으로 본다','가로는 원주의 반'),
('M6-2-u5-X16','math',6,'u5',ARRAY['M6-2-u5-C7']::text[],'고리 모양의 넓이를 반지름의 차로 만든 원의 넓이로 구하거나 작은 원을 빼지 않는다','큰 원 - 작은 원'),
('M6-2-u5-X17','math',6,'u5',ARRAY['M6-2-u5-C7']::text[],'잘라 옮기면 넓이가 변한다고 보거나, 반원·사분원·조각에서 나누기를 빠뜨리거나 잘못 나눈다','몇 조각 중 하나?'),
('M6-2-u5-X18','math',6,'u5',ARRAY['M6-2-u5-C2','M6-2-u5-C8']::text[],'반지름(지름)이 □배일 때 원주·넓이가 몇 배인지 잘못 본다(넓이도 □배, 원주도 □ × □배, 차이로 늘리기)','넓이는 □ × □배'),
('M6-2-u5-X19','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C2','M6-2-u5-C3','M6-2-u5-C4','M6-2-u5-C5','M6-2-u5-C6','M6-2-u5-C7','M6-2-u5-C8']::text[],'묻는 말을 거꾸로 읽는다 — 잘못된↔알맞은, 반지름↔지름, 큰↔작은','물음의 「잘못·않은」에 동그라미'),
('M6-2-u5-X20','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C2','M6-2-u5-C3','M6-2-u5-C4','M6-2-u5-C5','M6-2-u5-C6','M6-2-u5-C7','M6-2-u5-C8']::text[],'소수 곱셈·나눗셈의 자릿수나 단위(cm·m)를 바꾸는 계산을 잘못한다','어림해서 확인')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_2_math_u5_L02_basic#1','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'mc','auto','원의 둘레를 무엇이라고 하나요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"원의 둘레를 무엇이라고 하나요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X02"},{"t":"원의 중심","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."],"variant_rule":{"alt":[{"stem":"원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"반지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심과 원 위의 한 점을 이은 선분을 반지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]},{"stem":"원의 중심을 지나도록 원 위의 두 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심을 지나도록 원 위의 두 점을 이은 선분을 지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]}]}}'::jsonb),
('g6_2_math_u5_L02_basic#2','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'sa','auto','원 모양 얼음판의 지름은 16 m예요. 이 얼음판의 반지름은 몇 m인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"원 모양 얼음판의 지름은 16 m예요. 이 얼음판의 반지름은 몇 m인가요?","answer":["8"],"explanation":["반지름은 지름의 반이에요.","(반지름) = (지름) ÷ 2예요.","16 ÷ 2 = 8 — 반지름은 8 m예요."],"variant_rule":{"alt":[{"stem":"원 모양 얼음판의 지름은 24 m예요. 이 얼음판의 반지름은 몇 m인가요?","answer":["12"],"explanation":["반지름은 지름의 반이에요.","(반지름) = (지름) ÷ 2예요.","24 ÷ 2 = 12 — 반지름은 12 m예요."]},{"stem":"원 모양 얼음판의 지름은 30 m예요. 이 얼음판의 반지름은 몇 m인가요?","answer":["15"],"explanation":["반지름은 지름의 반이에요.","(반지름) = (지름) ÷ 2예요.","30 ÷ 2 = 15 — 반지름은 15 m예요."]}]}}'::jsonb),
('g6_2_math_u5_L02_basic#3','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'sa','auto','반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["16"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","8 × 2 = 16 — 지름은 16 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["12"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","6 × 2 = 12 — 지름은 12 cm예요."]},{"stem":"반지름이 9 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["18"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","9 × 2 = 18 — 지름은 18 cm예요."]}]}}'::jsonb),
('g6_2_math_u5_L02_basic#4','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'sa','auto','지름이 4 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"지름이 4 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["12"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 2이고 변이 6개이니 둘레는 2 × 6이에요.","2 × 6 = 12 — 지름의 3배인 12 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["18"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 3이고 변이 6개이니 둘레는 3 × 6이에요.","3 × 6 = 18 — 지름의 3배인 18 cm예요."]},{"stem":"지름이 8 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["24"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 4이고 변이 6개이니 둘레는 4 × 6이에요.","4 × 6 = 24 — 지름의 3배인 24 cm예요."]}]}}'::jsonb),
('g6_2_math_u5_L02_basic#5','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'sa','auto','지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["16"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 4 cm이고 변이 4개예요.","4 × 4 = 16 — 지름의 4배인 16 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["24"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 6 cm이고 변이 4개예요.","6 × 4 = 24 — 지름의 4배인 24 cm예요."]},{"stem":"지름이 7 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["28"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 7 cm이고 변이 4개예요.","7 × 4 = 28 — 지름의 4배인 28 cm예요."]}]}}'::jsonb),
('g6_2_math_u5_L02_basic#6','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'mc','auto','원 안에 꼭 맞는 정육각형의 한 변은 원의 무엇과 길이가 같나요?',ARRAY['M6-2-u5-X03','M6-2-u5-X02']::text[],true,'{"seq":6,"concept":"M6-2-u5-C1","difficulty":2,"kind":"mc","stem":"원 안에 꼭 맞는 정육각형의 한 변은 원의 무엇과 길이가 같나요?","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M6-2-u5-X03"},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"원주의 반","mis":"M6-2-u5-X02"}],"explanation":["정육각형은 원의 중심을 꼭짓점으로 하는 정삼각형 6개로 나뉘어요.","정삼각형의 두 변이 반지름이니 정육각형의 한 변도 반지름과 같아요.","그래서 정육각형의 둘레는 반지름의 6배, 곧 지름의 3배예요."],"variant_rule":{"alt":[{"stem":"원 밖에 꼭 맞는 정사각형의 한 변은 원의 무엇과 길이가 같나요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M6-2-u5-X03"},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"원주의 반","mis":"M6-2-u5-X02"}],"explanation":["정사각형이 원을 꼭 감싸면 마주 보는 두 변 사이가 원의 지름만큼 떨어져 있어요.","그래서 정사각형의 한 변은 지름과 같아요.","정사각형의 둘레는 지름의 4배예요."]},{"stem":"원 안에 꼭 맞는 정육각형의 둘레는 원의 지름의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"6배","mis":"M6-2-u5-X03"},{"t":"2배","mis":"M6-2-u5-X03"},{"t":"4배","mis":"M6-2-u5-X03"}],"explanation":["정육각형의 한 변은 반지름과 같아요.","변이 6개이니 둘레는 반지름의 6배예요.","반지름 2개가 지름이니 반지름의 6배는 지름의 3배예요."]}]}}'::jsonb),
('g6_2_math_u5_L02_basic#7','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'mc','auto','지름이 4 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":7,"concept":"M6-2-u5-C1","difficulty":2,"kind":"mc","stem":"지름이 4 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"12 cm보다 길고 16 cm보다 짧아요","correct":true},{"t":"8 cm보다 길고 12 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"16 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 12 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 12 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 16 cm예요.","원주는 그 사이 — 12 cm보다 길고 16 cm보다 짧아요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"18 cm보다 길고 24 cm보다 짧아요","correct":true},{"t":"12 cm보다 길고 18 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"24 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 18 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 18 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 24 cm예요.","원주는 그 사이 — 18 cm보다 길고 24 cm보다 짧아요."]},{"stem":"지름이 10 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"30 cm보다 길고 40 cm보다 짧아요","correct":true},{"t":"20 cm보다 길고 30 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"40 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 30 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 30 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 40 cm예요.","원주는 그 사이 — 30 cm보다 길고 40 cm보다 짧아요."]}]}}'::jsonb),
('g6_2_math_u5_L02_basic#8','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'ox','auto','원주는 지름의 정확히 3배예요.',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":8,"concept":"M6-2-u5-C1","difficulty":2,"kind":"ox","stem":"원주는 지름의 정확히 3배예요.","answer":"X","reason_options":[{"t":"원주는 원 안 정육각형의 둘레(지름의 3배)보다 길기 때문에","correct":true},{"t":"원 안 정육각형의 둘레가 지름의 3배이기 때문에","mis":"M6-2-u5-X02"}],"mis":"M6-2-u5-X02","explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."],"variant_rule":{"alt":[{"stem":"원주는 원 밖에 꼭 맞는 정사각형의 둘레보다 짧아요.","answer":"O","reason_options":[{"t":"꺾인 선보다 원의 굽은 선이 더 짧기 때문에","correct":true},{"t":"정사각형의 한 변이 반지름과 같기 때문에","mis":"M6-2-u5-X03"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."]},{"stem":"원의 둘레도 다각형처럼 변의 길이를 더해 구할 수 있어요.","answer":"X","reason_options":[{"t":"원에는 곧은 변이 하나도 없기 때문에","correct":true},{"t":"원의 변은 지름 하나뿐이라서 지름을 두 번 더하면 되기 때문에","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."]}]}}'::jsonb),
