('g6_2_math_u5_L02_basic#10','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',3,'mc','auto','지름이 10 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":10,"concept":"M6-2-u5-C1","difficulty":3,"kind":"mc","stem":"지름이 10 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"29 cm","mis":"M6-2-u5-X02"},{"t":"42 cm","mis":"M6-2-u5-X02"},{"t":"10 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 10 cm이면 원주는 30 cm와 40 cm 사이예요.","보기 가운데 그 사이에 있는 것은 31.4 cm뿐이에요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"18.84 cm","correct":true},{"t":"17 cm","mis":"M6-2-u5-X02"},{"t":"26 cm","mis":"M6-2-u5-X02"},{"t":"6 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 6 cm이면 원주는 18 cm와 24 cm 사이예요.","보기 가운데 그 사이에 있는 것은 18.84 cm뿐이에요."]},{"stem":"지름이 20 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"62.8 cm","correct":true},{"t":"59 cm","mis":"M6-2-u5-X02"},{"t":"82 cm","mis":"M6-2-u5-X02"},{"t":"20 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 20 cm이면 원주는 60 cm와 80 cm 사이예요.","보기 가운데 그 사이에 있는 것은 62.8 cm뿐이에요."]}]}}'::jsonb),
('g6_2_math_u5_L02_challenge#1','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',2,'sa','auto','지름이 10 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 10 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["30"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 5이고 변이 6개이니 둘레는 5 × 6이에요.","5 × 6 = 30 — 지름의 3배인 30 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 12 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 6이고 변이 6개이니 둘레는 6 × 6이에요.","6 × 6 = 36 — 지름의 3배인 36 cm예요."]},{"stem":"지름이 14 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["42"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 7이고 변이 6개이니 둘레는 7 × 6이에요.","7 × 6 = 42 — 지름의 3배인 42 cm예요."]}]}}'::jsonb),
